\end{equation}
After using Assumption (1) and (2),
\begin{equation}
\sum_{i=1}^\infty\left(\arctan\sqrt{n}-\arctan\sqrt{n+1}\right)\approx \frac{\pi}{4}(n-1)(1-\frac 1 {\sqrt{1+n}}).
\quad \text{(3)}
\end{equation}
